import { sql } from "drizzle-orm";
import { customType, timestamp, uuid } from "drizzle-orm/pg-core";
import { uuidv7 } from "../../lib/ids";

/** Primary key: UUIDv7 generated by the application (DB default exists only for hand-written SQL). */
export const pk = () =>
  uuid("id")
    .primaryKey()
    .default(sql`gen_random_uuid()`)
    .$defaultFn(() => uuidv7());

export const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });
export const createdAt = (name = "created_at") => tstz(name).notNull().defaultNow();

export const tsvector = customType<{ data: string; driverData: string }>({
  dataType: () => "tsvector",
});

/**
 * CHECK constraint helper for vocabulary columns. Values come from @ideaproxima/domain constants, so the
 * database and the code cannot silently disagree; changing a vocabulary produces a migration.
 */
export const inListSql = (column: string, values: readonly (string | number)[]): string =>
  `"${column}" in (${values.map((v) => (typeof v === "number" ? String(v) : `'${v}'`)).join(", ")})`;

export const inList = (column: string, values: readonly (string | number)[]) =>
  sql.raw(inListSql(column, values));

/** Same as `inList`, but NULL is also allowed. */
export const nullOrInList = (column: string, values: readonly (string | number)[]) =>
  sql.raw(`"${column}" is null or ${inListSql(column, values)}`);
